package com.lychcs.koikoi.graphics;

import com.lychcs.koikoi.TestAssetFiles;
import org.junit.jupiter.api.Test;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.nio.file.Path;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Validates the 128-colour palette texture used by the palette-swap shader. The
 * texture is generated by {@code tools/PngToAsciiConverter.java} from the master
 * ACT palette, so the GPU pass and the ASCII matrices share one palette.
 */
class PaletteAssetTest {

    @Test
    void paletteTextureIsA128x1OpaqueStrip() throws IOException {
        Path path = TestAssetFiles.assetRoot().resolve("palette/palette_128.png");
        BufferedImage image = ImageIO.read(path.toFile());

        assertNotNull(image, "palette texture missing: " + path);
        assertEquals(128, image.getWidth(), "palette width");
        assertEquals(1, image.getHeight(), "palette height");

        boolean anyVisible = false;
        for (int index = 0; index < image.getWidth(); index++) {
            int argb = image.getRGB(index, 0);
            assertEquals(255, (argb >>> 24) & 0xFF, "palette entry " + index + " must be opaque");
            anyVisible |= (argb & 0x00FFFFFF) != 0;
        }

        assertTrue(anyVisible, "the palette must contain visible colours");
        assertNotEquals(image.getRGB(0, 0), image.getRGB(1, 0),
            "palette entries must not collapse into one colour");
    }
}
